String cacheKey(String entity, long id, long version, String schemaVersion) {
    // schema version: a deploy that changes the payload shape is safe with no flush
    // entity version: an update writes a NEW key, so no reader can repopulate the old one
    return "%s:%s:%d:v%d".formatted(schemaVersion, entity, id, version);
}

Product read(long id) {
    long version = versions.current(id);          // cheap, authoritative, uncached
    return l2.get(cacheKey("product", id, version, SCHEMA), () -> db.load(id));
}

// an update bumps the version; nothing is deleted, and the old key ages out
void update(long id, ProductPatch patch) {
    db.apply(id, patch);
    versions.bump(id);
}

