// L = arrival rate x service time
//   250 rps peak x 0.040 s = 10 concurrent requests at the design peak
//
// so a bulkhead of ~12 (10 plus headroom) is the real limit. A 200-thread pool
// does not admit more work usefully; it hides 190 requests behind the limiter
// where queue age is invisible and the deadline expires unnoticed.

Bulkhead bulkhead = Bulkhead.of("checkout", BulkheadConfig.custom()
        .maxConcurrentCalls(12)
        .maxWaitDuration(Duration.ofMillis(50))   // fail fast: a long wait IS the outage
        .build());

Response handle(Request request) {
    if (request.deadline().isBefore(clock.instant())) {
        return Response.gone();          // the client already gave up; doing the work is pure loss
    }
    return bulkhead.executeSupplier(() -> service.handle(request));
}

// L = tốc độ đến x thời gian phục vụ
//   250 rps peak x 0,040 s = 10 request đồng thời tại peak thiết kế
//
// nên một bulkhead ~12 (10 cộng khoảng dư) mới là giới hạn thật. Một pool 200 thread
// không nhận thêm việc một cách hữu ích; nó giấu 190 request phía sau bộ giới hạn,
// nơi tuổi hàng đợi vô hình và deadline hết hạn mà không ai hay.

Bulkhead bulkhead = Bulkhead.of("checkout", BulkheadConfig.custom()
        .maxConcurrentCalls(12)
        .maxWaitDuration(Duration.ofMillis(50))   // hỏng nhanh: chờ lâu CHÍNH LÀ sự cố
        .build());

Response handle(Request request) {
    if (request.deadline().isBefore(clock.instant())) {
        return Response.gone();          // client đã bỏ cuộc; làm tiếp là mất trắng
    }
    return bulkhead.executeSupplier(() -> service.handle(request));
}

