void dispatch(Intent intent) {
    Recipient r = recipients.load(intent.recipientId());

    // suppression is absolute and is checked first: sending to a hard bounce or a
    // complaint is what damages sender reputation for every other message
    if (suppression.contains(r, intent.channel())) {
        intents.terminate(intent, SUPPRESSED);
        return;
    }

    // read now, not at accept time: the user may have opted out while this queued
    Preference p = preferences.current(r, intent.channel());
    if (!p.optedIn()) { intents.terminate(intent, OPTED_OUT); return; }

    if (p.inQuietHours(clock.now(), r.timezone()) && intent.priority() != TRANSACTIONAL) {
        intents.reschedule(intent, p.nextWindow(clock.now(), r.timezone()));
        return;
    }

    rateLimiter.forChannel(intent.channel()).acquire();   // provider limit, not ours
    providers.send(intent, render(intent, r.locale()));
}

void dispatch(Intent intent) {
    Recipient r = recipients.load(intent.recipientId());

    // suppression là tuyệt đối và được kiểm trước: gửi vào một hard bounce hay một
    // khiếu nại chính là thứ phá uy tín người gửi cho mọi message khác
    if (suppression.contains(r, intent.channel())) {
        intents.terminate(intent, SUPPRESSED);
        return;
    }

    // đọc ngay bây giờ, không đọc lúc nhận: người dùng có thể đã huỷ đăng ký trong lúc chờ
    Preference p = preferences.current(r, intent.channel());
    if (!p.optedIn()) { intents.terminate(intent, OPTED_OUT); return; }

    if (p.inQuietHours(clock.now(), r.timezone()) && intent.priority() != TRANSACTIONAL) {
        intents.reschedule(intent, p.nextWindow(clock.now(), r.timezone()));
        return;
    }

    rateLimiter.forChannel(intent.channel()).acquire();   // giới hạn của provider, không phải của ta
    providers.send(intent, render(intent, r.locale()));
}

public ResponseEntity<Void> resolve(String code) {
    Link link = cache.get(code, this::loadFromDb);   // one hit on the hot path

    if (link == null || link.revoked() || link.expired(clock.instant())) {
        return ResponseEntity.status(HttpStatus.GONE).build();
    }

    // 302, not 301: a permanent redirect is cached by the browser and the ISP,
    // so we would never see the click again and could not revoke the link.
    ResponseEntity<Void> response = ResponseEntity.status(HttpStatus.FOUND)
            .location(URI.create(link.destination()))
            .cacheControl(CacheControl.noStore())
            .build();

    clicks.offer(new ClickEvent(code, clock.instant(), classify(request)));  // bounded, may drop
    return response;
}

public ResponseEntity<Void> resolve(String code) {
    Link link = cache.get(code, this::loadFromDb);   // một hit duy nhất trên hot path

    if (link == null || link.revoked() || link.expired(clock.instant())) {
        return ResponseEntity.status(HttpStatus.GONE).build();
    }

    // 302 chứ không phải 301: redirect vĩnh viễn bị trình duyệt và ISP cache lại,
    // nên ta sẽ không bao giờ thấy cú click đó nữa và không thu hồi được link.
    ResponseEntity<Void> response = ResponseEntity.status(HttpStatus.FOUND)
            .location(URI.create(link.destination()))
            .cacheControl(CacheControl.noStore())
            .build();

    clicks.offer(new ClickEvent(code, clock.instant(), classify(request)));  // có chặn trên, có thể rơi
    return response;
}

List<Entry> homeTimeline(long userId, long cursor, int limit) {
    // pushed candidates: one partition read
    List<Entry> pushed = timeline.page(userId, cursor, limit * 2);

    // pulled candidates: only the accounts too large to fan out, and the set is
    // capped so a user who follows 400 celebrities cannot uncap the read.
    List<Long> celebrities = follows.highFanout(userId, MAX_MERGE_SOURCES);
    List<Entry> pulled = posts.recentByAuthors(celebrities, cursor, limit * 2);

    List<Entry> merged = mergeByPostIdDesc(pushed, pulled);

    // authorization happens here, on the merged candidates, because a stored
    // timeline entry predates the block or privacy change that may have followed it
    List<Entry> visible = visibility.filter(userId, merged);

    return ranker.rankOrFallback(userId, visible, limit);
}

List<Entry> homeTimeline(long userId, long cursor, int limit) {
    // ứng viên đã đẩy: một lượt đọc partition
    List<Entry> pushed = timeline.page(userId, cursor, limit * 2);

    // ứng viên kéo về: chỉ những tài khoản quá lớn để fan-out, và tập này bị
    // chặn trên để một người follow 400 người nổi tiếng không làm lượt đọc mất chặn.
    List<Long> celebrities = follows.highFanout(userId, MAX_MERGE_SOURCES);
    List<Entry> pulled = posts.recentByAuthors(celebrities, cursor, limit * 2);

    List<Entry> merged = mergeByPostIdDesc(pushed, pulled);

    // kiểm quyền xem ở đây, trên tập đã merge, vì một entry timeline đã lưu có
    // trước lệnh block hay thay đổi quyền riêng tư xảy ra sau đó
    List<Entry> visible = visibility.filter(userId, merged);

    return ranker.rankOrFallback(userId, visible, limit);
}

long rankingValue(long score, Instant achievedAt) {
    // score in the high bits, inverted time in the low bits: a later time lowers
    // the value, so an equal score is broken in favour of whoever got there first
    long invertedTime = MAX_EPOCH_SECONDS - achievedAt.getEpochSecond();
    return (score << TIME_BITS) | (invertedTime & TIME_MASK);
}

void submit(String board, long playerId, long score, Instant at) {
    // absolute score, not a delta: replaying this event twice is a no-op
    redis.zadd(board, rankingValue(score, at), String.valueOf(playerId));
}

long rankingValue(long score, Instant achievedAt) {
    // điểm ở bit cao, thời gian đảo ở bit thấp: thời gian muộn hơn làm giá trị nhỏ đi,
    // nên điểm bằng nhau sẽ phá hoà theo hướng ai đạt được trước thì thắng
    long invertedTime = MAX_EPOCH_SECONDS - achievedAt.getEpochSecond();
    return (score << TIME_BITS) | (invertedTime & TIME_MASK);
}

void submit(String board, long playerId, long score, Instant at) {
    // điểm tuyệt đối, không phải delta: phát lại event này hai lần là vô hại
    redis.zadd(board, rankingValue(score, at), String.valueOf(playerId));
}

Value get(String key) {
    Value hit = cache.get(key);
    if (hit != null && !hit.nearExpiry()) return hit;

    // probabilistic early refresh: one reader renews slightly before expiry so the
    // key is never simultaneously missing for everyone
    if (hit != null && !shouldEarlyRefresh(hit)) return hit;

    // one loader per key per process; the rest wait on the same future rather
    // than each issuing their own origin call
    return inFlight.computeIfAbsent(key, k -> CompletableFuture.supplyAsync(() -> {
        Value fresh = origin.load(k);
        cache.put(k, fresh, ttlWithJitter());   // jitter: batch writes must not expire together
        return fresh;
    })).whenComplete((v, e) -> inFlight.remove(key)).join();
}

Value get(String key) {
    Value hit = cache.get(key);
    if (hit != null && !hit.nearExpiry()) return hit;

    // làm mới sớm theo xác suất: một người đọc gia hạn hơi trước khi hết hạn, nên
    // khoá không bao giờ đồng thời biến mất với tất cả mọi người
    if (hit != null && !shouldEarlyRefresh(hit)) return hit;

    // một loader cho mỗi khoá trong mỗi tiến trình; những người còn lại chờ trên
    // cùng một future thay vì mỗi người tự gọi origin một lần
    return inFlight.computeIfAbsent(key, k -> CompletableFuture.supplyAsync(() -> {
        Value fresh = origin.load(k);
        cache.put(k, fresh, ttlWithJitter());   // rắc nhiễu: lô ghi cùng lúc không được hết hạn cùng lúc
        return fresh;
    })).whenComplete((v, e) -> inFlight.remove(key)).join();
}

void onReconnect(Session session, long conversationId, long lastSeenSeq) {
    // the client states its position; the server never guesses it from a timestamp
    long head = sequences.head(conversationId);

    if (head - lastSeenSeq > CATCH_UP_LIMIT) {
        // too far behind to stream: hand back a snapshot pointer and let the
        // client paginate history instead of replaying a million messages
        session.send(new ResyncRequired(conversationId, head));
        return;
    }

    for (Message m : messages.range(conversationId, lastSeenSeq + 1, head)) {
        session.send(m);
    }
    cursors.markDelivered(session.deviceId(), conversationId, head);
}

void onReconnect(Session session, long conversationId, long lastSeenSeq) {
    // client tự khai vị trí của nó; server không bao giờ đoán từ một timestamp
    long head = sequences.head(conversationId);

    if (head - lastSeenSeq > CATCH_UP_LIMIT) {
        // tụt quá xa để stream: trả về một con trỏ snapshot và để client phân
        // trang lịch sử thay vì phát lại cả triệu tin nhắn
        session.send(new ResyncRequired(conversationId, head));
        return;
    }

    for (Message m : messages.range(conversationId, lastSeenSeq + 1, head)) {
        session.send(m);
    }
    cursors.markDelivered(session.deviceId(), conversationId, head);
}

List<Suggestion> complete(String raw, Locale locale, UserId user) {
    String prefix = normalize(raw, locale);         // must match the build-time normalizer
    if (prefix.length() < MIN_PREFIX) return List.of();

    // the index version is part of the key, so a rollout invalidates by construction
    CacheKey key = new CacheKey(prefix, locale, index.version());
    List<Suggestion> candidates = cache.get(key, () -> index.topN(prefix, locale, N));

    // read live, not from the artifact: a term blocked at noon must vanish at noon
    List<Suggestion> allowed = policy.filter(candidates);

    return reranker.rerankOrIdentity(user, allowed, LIMIT);
}

void activate(IndexArtifact candidate) {
    candidate.load();                       // both versions resident: this is the memory budget
    warmup.run(candidate, hottestPrefixes); // pay the page faults before users do

    if (!health.check(candidate)) {
        candidate.close();
        throw new RolloutRejected(candidate.version());
    }

    IndexArtifact previous = current.getAndSet(candidate);  // atomic pointer swap
    scheduler.schedule(previous::close, DRAIN_WINDOW);      // in-flight reads finish on the old one
}

List<Suggestion> complete(String raw, Locale locale, UserId user) {
    String prefix = normalize(raw, locale);         // phải khớp bộ chuẩn hoá lúc build
    if (prefix.length() < MIN_PREFIX) return List.of();

    // version index nằm trong khoá, nên một đợt tung tự vô hiệu hoá cache theo cấu trúc
    CacheKey key = new CacheKey(prefix, locale, index.version());
    List<Suggestion> candidates = cache.get(key, () -> index.topN(prefix, locale, N));

    // đọc sống, không đọc từ artifact: từ bị chặn lúc trưa phải biến mất lúc trưa
    List<Suggestion> allowed = policy.filter(candidates);

    return reranker.rerankOrIdentity(user, allowed, LIMIT);
}

void activate(IndexArtifact candidate) {
    candidate.load();                       // hai version cùng nằm trong bộ nhớ: đây là ngân sách bộ nhớ
    warmup.run(candidate, hottestPrefixes); // trả trước phần page fault thay vì để người dùng trả

    if (!health.check(candidate)) {
        candidate.close();
        throw new RolloutRejected(candidate.version());
    }

    IndexArtifact previous = current.getAndSet(candidate);  // đổi con trỏ nguyên tử
    scheduler.schedule(previous::close, DRAIN_WINDOW);      // lượt đọc đang dở kết thúc trên bản cũ
}

UploadSession initiate(String key, long size, UserId owner) {
    int partSize = choosePartSize(size);        // measured, not a constant
    return sessions.create(key, owner, partSize, storage.initiateMultipart(key));
}

URI urlForPart(String uploadId, int partNumber) {
    UploadSession s = sessions.require(uploadId);
    // short-lived and scoped to exactly one part of one object: a leaked URL
    // cannot be replayed against another key or after the window
    return storage.presignPart(s.storageKey(), s.storageUploadId(), partNumber, PART_URL_TTL);
}

ObjectRef complete(String uploadId, List<PartAssertion> claimed) {
    UploadSession s = sessions.require(uploadId);
    List<PartRecord> recorded = parts.listFor(uploadId);

    // validate BEFORE publishing the key: a half-assembled object must never be readable
    if (!manifestMatches(claimed, recorded)) throw new IntegrityMismatch(uploadId);

    return storage.completeMultipart(s.storageKey(), s.storageUploadId(), recorded);
}

UploadSession initiate(String key, long size, UserId owner) {
    int partSize = choosePartSize(size);        // đo được, không phải hằng số
    return sessions.create(key, owner, partSize, storage.initiateMultipart(key));
}

URI urlForPart(String uploadId, int partNumber) {
    UploadSession s = sessions.require(uploadId);
    // tuổi thọ ngắn và giới hạn đúng một part của đúng một object: một URL bị lộ
    // không thể phát lại lên khoá khác hay sau khi hết cửa sổ
    return storage.presignPart(s.storageKey(), s.storageUploadId(), partNumber, PART_URL_TTL);
}

ObjectRef complete(String uploadId, List<PartAssertion> claimed) {
    UploadSession s = sessions.require(uploadId);
    List<PartRecord> recorded = parts.listFor(uploadId);

    // kiểm TRƯỚC khi công bố khoá: một object ráp dở không bao giờ được đọc được
    if (!manifestMatches(claimed, recorded)) throw new IntegrityMismatch(uploadId);

    return storage.completeMultipart(s.storageKey(), s.storageUploadId(), recorded);
}

