const queue: Job[] = [];
const MAX_QUEUE = 500;

export function enqueue(job: Job) {
  if (queue.length >= MAX_QUEUE) {
    throw new Error('OVERLOADED_RETRY_LATER');
  }
  queue.push(job);
}

setInterval(async () => {
  const job = queue.shift();
  if (job) await handle(job);
}, 10);

