BEGIN;

SELECT job_id, estimated_cost
FROM job
WHERE tenant_id = :tenant_id
  AND state = 'RUNNABLE'
  AND estimated_cost <= :deficit
ORDER BY created_at
FOR UPDATE SKIP LOCKED
LIMIT :batch_size;

UPDATE job
SET state = 'LEASED', lease_until = now() + interval '30 seconds'
WHERE job_id = ANY(:job_ids);

COMMIT;

